import { test } from 'node:test';
import assert from 'node:assert/strict';
import { fromWatchPage, isoSeconds, lookupYoutubeMeta, parseTopicDescription } from '../src/catalog/youtube-meta.js';
import { YoutubeUnavailable } from '../src/catalog/youtube.js';

const TOPIC = "Provided to YouTube by Static Shock\n\nGod's Chest · Uranium Club\n\nAll Of Them Naturals\n\n" +
  '℗ 2016 Static Shock\n\nReleased on: 2017-01-13\n\nMain Artist: Uranium Club\n\nAuto-generated by YouTube.';
const ID = 'VxuNvoiel2g', OTHER = 'H_AKKQ-f9LM';
const fast = { pause: async () => {} };

function watchPage({ status = 'OK', reason, details = true } = {}) {
  const player = { playabilityStatus: { status, ...(reason ? { reason } : {}) },
    ...(details ? { videoDetails: { videoId: ID, title: "God's Chest", lengthSeconds: '258', author: 'Uranium Club - Topic',
      viewCount: '1550', shortDescription: TOPIC, keywords: ['Uranium Club'] } } : {}) };
  return `<html><script>var ytInitialPlayerResponse = ${JSON.stringify(player)};var meta = {};</script></html>`;
}
const page = (html, status = 200) => ({ ok: status === 200, status, url: 'https://www.youtube.com/watch', text: async () => html });

test('label uploads describe their album, label and dates', () => {
  assert.deepEqual(parseTopicDescription(TOPIC), { album: 'All Of Them Naturals', label: 'Static Shock', year: 2016, released: '2017-01-13' });
  assert.deepEqual(parseTopicDescription("Provided to YouTube by X\n\nSong · Artist\n\n℗ Hi Records\n\nAuto-generated by YouTube."),
    { album: null, label: 'Hi Records', year: null, released: null });
  assert.deepEqual(parseTopicDescription('Official video. ℗ 2016 Not a label line'), { album: null, label: null, year: null, released: null });
});

test('ISO durations read as seconds', () => {
  assert.deepEqual(['PT4M18S', 'PT1H2M3S', 'PT45S', 'P0D', 'PT0S', 'nonsense', null].map(isoSeconds), [258, 3723, 45, null, null, null, null]);
});

test('a watch page gives the length and description the player is handed', () => {
  assert.deepEqual(fromWatchPage(watchPage()), { length: 258, channel: 'Uranium Club - Topic', views: 1550,
    album: 'All Of Them Naturals', label: 'Static Shock', year: 2016, released: '2017-01-13' });
  assert.equal(fromWatchPage(watchPage({ status: 'ERROR', details: false })), null);
  assert.throws(() => fromWatchPage(watchPage({ status: 'LOGIN_REQUIRED', reason: "Sign in to confirm you're not a bot", details: false })), YoutubeUnavailable);
});

test('with a key, the Data API answers 50 videos per request, and deleted videos are marked', async () => {
  const urls = [];
  const fetchImpl = async (url) => {
    urls.push(url);
    const items = new URL(url).searchParams.get('id').split(',').filter((id) => id === ID)
      .map((id) => ({ id, snippet: { channelTitle: 'Uranium Club - Topic', description: TOPIC }, contentDetails: { duration: 'PT4M18S' }, statistics: { viewCount: '1550' } }));
    return { ok: true, status: 200, json: async () => ({ items }) };
  };
  const ids = [ID, OTHER, ...Array.from({ length: 60 }, (_, i) => `x${String(i).padStart(10, '0')}`)];
  const { cache, done, error } = await lookupYoutubeMeta(ids, { apiKey: 'KEY', fetchImpl, ...fast });
  assert.equal(error, null);
  assert.equal(done, 62);
  assert.equal(urls.length, 2);
  assert.ok(urls[0].includes('key=KEY') && urls[0].startsWith('https://www.googleapis.com/youtube/v3/videos?'));
  assert.deepEqual([cache[ID].length, cache[ID].album, cache[ID].found], [258, 'All Of Them Naturals', true]);
  assert.deepEqual([cache[OTHER].length, cache[OTHER].found], [null, false]);
});

test('a refused key stops the run without recording anything', async () => {
  const fetchImpl = async () => ({ ok: false, status: 403, json: async () => ({ error: { message: 'API key not valid' } }) });
  const { cache, error } = await lookupYoutubeMeta([ID], { apiKey: 'BAD', fetchImpl, ...fast });
  assert.match(error.message, /API key not valid/);
  assert.deepEqual(cache, {});
});

test('without a key, watch pages are read one by one, waiting out limits before stopping', async () => {
  const pauses = [];
  let limited = 1;
  const fetchImpl = async (url) => {
    if (url.includes(OTHER) && limited-- > 0) return { ok: false, status: 429, url, text: async () => '' };
    return page(watchPage());
  };
  const backoffs = [];
  const run = await lookupYoutubeMeta([ID, OTHER], { fetchImpl, delayMs: 15000, backoffs: [120000],
    pause: async (ms) => { pauses.push(ms); }, onBackoff: ({ waitMs }) => backoffs.push(waitMs) });
  assert.equal(run.error, null);
  assert.deepEqual(backoffs, [120000]);
  assert.ok(pauses.filter((ms) => ms === 15000).length >= 2, 'pages are spaced out');
  assert.equal(Object.keys(run.cache).length, 2);

  const alwaysLimited = async (url) => ({ ok: false, status: 429, url, text: async () => '' });
  const stopped = await lookupYoutubeMeta([ID, OTHER], { cache: { [ID]: run.cache[ID] }, fetchImpl: alwaysLimited, backoffs: [1], ...fast });
  assert.match(stopped.error.message, /limiting/);
  assert.deepEqual(Object.keys(stopped.cache), [ID], 'a limited video is not recorded');
});
